def MediumAtom.q1SliceAtom (d : MediumAtom) (p : ℕ) : MediumAtom :=
  { d with gamma1 := fun q ↦ if q = p then 1 else 0 }

def MediumAtom.primitiveFirstFactorCarrier (d : MediumAtom) : Finset ℕ :=
  (factorCarrier d.Q1).filter (fun p ↦ p.Coprime d.residue.natAbs)

def MediumAtom.sharedFirstFactorRows (d : MediumAtom) : Finset ((ℕ × ℕ) × ℕ) :=
  (factorCarrier d.Q2 ×ˢ factorCarrier d.Q3) ×ˢ d.transposedAtom.betaCarrier

def MediumAtom.sharedFirstFactorCoefficient (d : MediumAtom)
    (l : (ℕ × ℕ) × ℕ) : ℂ :=
  d.gamma2 l.1.1 * d.gamma3 l.1.2 * d.transposedAtom.beta l.2

def MediumAtom.cleanedAlpha (d : MediumAtom) (n : ℕ) : ℂ :=
  if (n : ℤ) ∣ d.residue then 0 else d.alpha n

def MediumAtom.divisorAlpha (d : MediumAtom) (n : ℕ) : ℂ :=
  if (n : ℤ) ∣ d.residue then d.alpha n else 0

def MediumAtom.cleanedAlphaAtom (d : MediumAtom) : MediumAtom :=
  { d with alpha := d.cleanedAlpha }

def shiftDifference (d : MediumAtom) (v : ℕ) : ℕ :=
  ((v : ℤ) - d.residue).natAbs

def tau (v : ℕ) : ℝ := (v.divisors.card : ℝ)

def fourthDivisorWeight (d : MediumAtom) (v : ℕ) : ℝ :=
  (fouvryTau 4 (shiftDifference d v) : ℝ) ^ 4

def productCarrier (d : MediumAtom) : Finset ℕ :=
  (Ioc 0 (Nat.floor (6 * d.scale))).filter (fun v => (v : ℤ) ≠ d.residue)

/-- The literal actual row, including its signed divisor-deletion gate. -/
def rowSum (d : MediumAtom) (p m : ℕ) : ℝ :=
  ∑ n ∈ d.cleanedCommonPProgression p m,
    ‖d.cleanedAlphaAtom.transposedAtom.beta n‖ *
      (fouvryTau 4 (shiftDifference d (m * n)) : ℝ) ^ 2

def moment (d : MediumAtom) : ℝ :=
  ∑ p ∈ d.primitiveFirstFactorCarrier,
    ∑ m ∈ d.cleanedAlphaAtom.transposedAtom.commonSmoothCarrier,
      d.cleanedAlphaAtom.transposedAtom.commonSmoothWeight m * rowSum d p m ^ 2

def MediumAtom.physicalFactorModuli (d : MediumAtom) : Finset ℕ :=
  d.complexFactorLabels.image complexFactorModulus

def MediumAtom.physicalFactorFiber (d : MediumAtom) (q : ℕ) : Finset (ℕ × ℕ × ℕ) :=
  d.complexFactorLabels.filter (fun r ↦ complexFactorModulus r = q)

def MediumAtom.commonSmoothCarrier (d : MediumAtom) : Finset ℕ :=
  Finset.Icc 0 (Nat.ceil (3 * d.U))

def MediumAtom.commonSmoothWeight (d : MediumAtom) (n : ℕ) : ℝ :=
  CommonSmoothCutoff.scaledDyadicCutoff d.U (n : ℝ)

theorem MediumAtom.commonSmoothWeight_nonneg (d : MediumAtom) (n : ℕ) :
    0 ≤ d.commonSmoothWeight n := CommonSmoothCutoff.scaledDyadicCutoff_nonneg _ _
